import type { RoutePath } from "expo-router";
import type { AnalyticsTracker } from "@/infrastructure/analytics/analytics-tracker";

/**
 * Every event the app logs, mapped to its parameters (`undefined` for none).
 * Add an entry when a module port needs an event, preferring Google Analytics
 * recommended events, for example `share: { content_type: string; method: string }`.
 * The template defines none, so `logEvent` accepts no name yet.
 */
export type AppAnalyticsEvents = Record<never, never>;

/**
 * Route patterns generated by Expo Router typed routes (`.expo/types`). Without
 * generated types, such as on a fresh checkout, this widens to `string`.
 */
export type AppScreen = RoutePath;

export type AppAnalyticsTracker = AnalyticsTracker<
  AppAnalyticsEvents,
  AppScreen
>;
